use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl < 'i > ParamValue < 'i > { # [doc = " Tries to create a new `ParamValue` from an escaped sequence, primarily for testing."] # [doc = ""] # [doc = " Validates the sequence and counts the number of escapes."] pub fn try_from_escaped (escaped : & 'i str) -> Result < Self , String > { let mut escapes = 0 ; let mut pos = 0 ; while pos < escaped . len () { let slash = memchr :: memchr (b'\\' , & escaped . as_bytes () [pos ..]) . map (| off | pos + off) ; for i in pos .. slash . unwrap_or (escaped . len ()) { if (char_classes (escaped . as_bytes () [i]) & C_QDTEXT) == 0 { return Err (format ! ("{:?} has non-qdtext at byte {}" , escaped , i)) ; } } if let Some (slash) = slash { escapes += 1 ; if escaped . len () <= slash + 1 { return Err (format ! ("{:?} ends at a quoted-pair escape" , escaped)) ; } if (char_classes (escaped . as_bytes () [slash + 1]) & C_ESCAPABLE) == 0 { return Err (format ! ("{:?} has an invalid quote-pair escape at byte {}" , escaped , slash + 1)) ; } pos = slash + 2 ; } else { break ; } } Ok (Self { escaped , escapes }) } # [doc = " Creates a new param, panicking if invariants are not satisfied."] # [doc = " This is not part of the stable API; it's just for the fuzz tester to use."] # [doc (hidden)] pub fn new (escapes : usize , escaped : & 'i str) -> Self { let mut pos = 0 ; for escape in 0 .. escapes { match memchr :: memchr (b'\\' , & escaped . as_bytes () [pos ..]) { Some (rel_pos) => pos += rel_pos + 2 , None => { panic ! ("expected {} backslashes in {:?}, ran out after {}" , escapes , escaped , escape) } } ; } if memchr :: memchr (b'\\' , & escaped . as_bytes () [pos ..]) . is_some () { panic ! ("expected {} backslashes in {:?}, are more" , escapes , escaped) ; } ParamValue { escapes , escaped } } # [doc = " Appends the unescaped form of this parameter to the supplied string."] pub fn append_unescaped (& self , to : & mut String) { to . reserve (self . escaped . len () - self . escapes) ; let mut first_unwritten = 0 ; for _ in 0 .. self . escapes { let i = match memchr :: memchr (b'\\' , & self . escaped . as_bytes () [first_unwritten ..]) { Some (rel_i) => first_unwritten + rel_i , None => { panic ! ("bad ParamValues; not as many backslash escapes as promised") } } ; to . push_str (& self . escaped [first_unwritten .. i]) ; to . push_str (& self . escaped [i + 1 .. i + 2]) ; first_unwritten = i + 2 ; } to . push_str (& self . escaped [first_unwritten ..]) ; } # [doc = " Returns the unescaped length of this parameter; cheap."] # [inline] pub fn unescaped_len (& self) -> usize { self . escaped . len () - self . escapes } # [doc = " Returns the unescaped form of this parameter as a fresh `String`."] pub fn to_unescaped (& self) -> String { let mut to = String :: new () ; self . append_unescaped (& mut to) ; to } # [doc = " Returns the unescaped form of this parameter, possibly appending it to `scratch`."] # [cfg (feature = "digest-scheme")] fn unescaped_with_scratch < 'tmp > (& self , scratch : & 'tmp mut String) -> & 'tmp str where 'i : 'tmp , { if self . escapes == 0 { self . escaped } else { let start = scratch . len () ; self . append_unescaped (scratch) ; & scratch [start ..] } } # [doc = " Returns the escaped string, unquoted."] # [inline] pub fn as_escaped (& self) -> & 'i str { self . escaped } }